               (("Step 1", "Étape 1"), ("Drop the class recording", "Déposez l'enregistrement du cours"), ("Transcribed on your device.", "Transcrit sur votre appareil."), "mosaic-capture", [3, 21, 94, 60]),
               (("Step 2", "Étape 2"), ("Read the note Claude wrote", "Lisez la note écrite par Claude"), ("Chapters that replay the moment.", "Des chapitres qui rejouent le moment."), "mosaic-chapters", [9, 58, 84, 34]),
               (("Step 3", "Étape 3"), ("Explain it back", "Expliquez-le à votre tour"), ("See what you missed.", "Voyez ce qui vous a échappé."), "mosaic-teach", [3, 37, 94, 44]),
