# Derived views for build.py: English dicts, and French overlays keyed by slug.
def _en(pair): return pair[0]
def _fr(pair): return pair[1]

PROJECTS, PROJECTS_FR, GUIDES, GUIDES_FR = [], {}, {}, {}
for P in PLATFORMS:
    g = P["guide"]
    PROJECTS.append({
        "slug": P["slug"], "n": P["n"], "title": P["title"], "year": P["year"], "color": P["color"], "ink": P["ink"],
        "url": P["url"], "link_label": _en(P["link_label"]), "shot": P["shot"], "stack": P["stack"],
        "kind": _en(P["kind"]), "status": _en(P["status"]), "line": _en(P["line"]),
        "facts": [(_en(k), _en(v)) for k, v in P["facts"]],
        "sections": [(_en(h), _en(x)) for h, x in P["sections"]],
        "beats": [{"t": en, "fr": fr, "s": s} for en, fr, s in P["beats"]],
    })
    PROJECTS_FR[P["slug"]] = {
        "kind": _fr(P["kind"]), "status": _fr(P["status"]), "line": _fr(P["line"]), "link_label": _fr(P["link_label"]),
        "facts": [(_fr(k), _fr(v)) for k, v in P["facts"]],
        "sections": [(_fr(h), _fr(x)) for h, x in P["sections"]],
    }
    GUIDES[P["slug"]] = {
        "audience": _en(g["audience"]),
        "start": [_en(x) for x in g["start"]],
        "rooms": [{"title": _en(r["title"]), "shot": r["shot"], "text": _en(r["text"]), "how": [_en(h) for h in r["how"]]} for r in g["features"]],
        "tips": [_en(x) for x in g["tips"]],
        "faq": [(_en(q), _en(a)) for q, a in g["faq"]],
        "contact": [(_en(l), h) for l, h in g["contact"]],
        "scenes": [{"k": _en(k), "t": _en(t), "c": _en(c), "shot": sh, "f": f} for k, t, c, sh, f in g["scenes"]],
    }
    GUIDES_FR[P["slug"]] = {
        "audience": _fr(g["audience"]),
        "start": [_fr(x) for x in g["start"]],
        "rooms": [(_fr(r["title"]), _fr(r["text"]), [_fr(h) for h in r["how"]]) for r in g["features"]],
        "tips": [_fr(x) for x in g["tips"]],
        "faq": [(_fr(q), _fr(a)) for q, a in g["faq"]],
        "contact": [_fr(l) for l, h in g["contact"]],
        "scenes": [(_fr(k), _fr(t), _fr(c)) for k, t, c, sh, f in g["scenes"]],
    }
